 64	void poisson_pe(i_dt image[Side1][Side1], int intensity, sr_dt spike_reg[MaxNeurons],
 65			sc_dt spike_cnt[MaxNeurons], sr_dt *spike_input, w_dt sf) {
 66	#pragma HLS INLINE off
 67	
 68		bool flag;
 69		int temp_reg[TSims/Sims], temp_cnt[TSims/Sims];
 70	   static unsigned int lfsr = 123456789 & 0x7fffffff;
 71	   unsigned int bit;
 72	   unsigned int random_int;
 73	
 74	   int accum_cnt;
 75	
 76	   int ASims = TSims/Sims;
 77	   int LSims;
 78	
 79	   if (ASims==1) {
 80	   	LSims = 2;
 81	   } else {
 82	   	LSims = ASims;
 83	   }
 84	
 85		L1: for (int i = 0; i < Side1; i++) {
 86			L2: for (int j = 0; j < Side1; j++) {
 87				L3: for (int s = 0;  s < LSims; s++) {
 88	#pragma HLS PIPELINE
 89	#pragma HLS DEPENDENCE variable=spike_reg inter false
 90	#pragma HLS DEPENDENCE variable=spike_cnt inter false
 91					if (s<ASims) {
 92						if (s==0) {
 93							flag = false;
 94							accum_cnt = 0;
 95						}
 96						L4: for (int sims = 0;  sims < Sims; sims++) {
 97	#pragma HLS UNROLL
 98							if (sims==0) {
 99								temp_reg[s] = 0;
100								temp_cnt[s] = 0;
101							}
102							bit = ((lfsr >> 0) ^ (lfsr >> 2) ^ (lfsr >> 3) ^ (lfsr >> 5)) & 1;
103							lfsr = (lfsr >> 1) | (bit << 31);
104							random_int = lfsr & 0x7fffffff;
105							if ((image[i][j] * intensity) > (random_int)) {
106								flag = true;
107								temp_reg[s] = i*Side1+j;
108								temp_cnt[s] += 1;
109							}
110						}
111						accum_cnt +=  temp_cnt[s];
112						if ((s==(ASims-1)) && flag) {
113							spike_reg[*spike_input] = temp_reg[s];
114							spike_cnt[*spike_input] = accum_cnt;
115							(*spike_input)++;
116						}
117					}
118				}
119			}
120		}
121	}
